SELECT DISTINCT ug.id as ug_id, u.id , u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email, u.user_mobile,u.user_tag,u.qq,u.weixin, p.id as position_id,u.be_lock, CONCAT(GROUP_CONCAT(DISTINCT r.role_name)) AS userRoles, CONCAT(GROUP_CONCAT(DISTINCT r.id)) AS userRoleIds, p.post_name,u.expire_time, u.create_time, u.create_user_cn_name, u.state, u.avatar, u.note FROM sys_user_group ug LEFT JOIN sys_user u ON u.id = ug.user_id LEFT JOIN sys_user_position up ON u.id = up.user_id AND up.group_id = ug.group_id LEFT JOIN sys_position p ON up.position_id = p.id LEFT JOIN sys_user_role AS ur ON u.id = ur.user_id AND ur.org_id = #{groupId,jdbcType=CHAR} LEFT JOIN sys_role AS r ON ur.role_id = r.id
ug.group_id = #{groupId,jdbcType=CHAR}
GROUP BY ug.id, u.id , u.user_no, u.user_real_cn_name, u.user_real_en_name, u.user_sex, u.user_email, u.user_mobile,u.user_tag,u.qq,u.weixin,p.id, p.post_name,u.be_lock, u.expire_time, u.create_time, u.state, u.avatar, u.note ORDER BY u.user_no desc LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

SELECT u.id,u.user_no,u.user_real_cn_name,u.user_real_en_name,u.user_email,u.user_mobile, ug.group_id,u.line_phone FROM sys_user u INNER JOIN sys_user_group ug ON ug.user_id = u.id WHERE u.state = 'ACTIVE' AND u.user_real_cn_name in
#{item}
order by u.create_time
